// rowTileClass picks the glyph-tile background+text for a session row: a soft
// hue wash for assigned projects, an orange "attention" wash when unassigned.
func rowTileClass(hue string, unassigned bool) string {
	if unassigned {
		return "bg-orange/10 text-orange"
	}
	switch hue {
	case "blue", "cyan", "green", "purple", "magenta", "yellow", "orange", "red", "teal":
		return "bg-" + hue + "/10 text-" + hue
	default:
		return "bg-sunken text-body"
	}
}

// rowShellClass picks the row container chrome: a solid card for assigned
// sessions, a dashed "empty" frame with a faint warning wash when unassigned.
func rowShellClass(unassigned bool) string {
	if unassigned {
		return " border-[1.5px] border-dashed border-faint bg-orange/[.05] px-3.5 py-3"
	}
	return " bg-surface border border-line px-3.5 py-3"
}

